import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(inp):
    g=[r[:] for r in inp]; H=len(g)
    # background rows between separators: split by full-5 rows
    segs=[]; cur=[]
    for r in range(H):
        if all(v==5 for v in g[r]): 
            if cur: segs.append(cur); cur=[]
        else: cur.append(r)
    segs.append(cur)
    tops, bot = segs[0], segs[-1]
    def collect(start, end):
        seen=set(); out=[]
        for r in range(start,end+1):
            for c,v in enumerate(g[r]):
                if v and (r,c) not in seen:
                    seen.add((r,c)); out.append((r,c,v))
        return out
    topsh=collect(tops[0],tops[-1]); botsh=collect(bot[0],bot[-1])
    # match: shape in top whose cell pattern (relative coords) equals a shape in bottom
    import collections
    def pat(cells):
        mr=min(r for r,c,v in cells); mc=min(c for r,c,v in cells)
        return tuple(sorted((r-mr,c-mc,v) for r,c,v in cells))
    botpats=collections.defaultdict(list)
    for p in botsh: botpats[pat(p)].append(p)
    dup=None
    for p in topsh:
        if pat(p) in botpats:
            dup=p; break
    # candidate others: unique colors, prefer rightmost then highest
    cands=[p for p in topsh if pat(p) not in botpats]
    cands.sort(key=lambda p:(-max(c for r,c,v in p), -v))
    sel=cands[0] if cands else None
    # place selector adjacent above dup, same columns
    br=max(r for r,c,v in botsh); tr=br-1
    for r,c,v in sel:
        rr=r+(tr-br)  # align so bottom of selector sits just above bottom of dup
        g[rr][c]=v
    return g

