    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import defaultdict
def pat(c):
    mr=min(p[0] for p in c); mc=min(p[1] for p in c)
    return sorted((p[0]-mr,p[1]-mc) for p in c)
def segs_of(gi):
    segs=[]; cur=[]
    for r in range(len(gi)):
        if all(v==5 for v in gi[r]):
            if cur: segs.append(cur); cur=[]
        else: cur.append(r)
    segs.append(cur)
    return segs
for n in [1,2,3,4]:
    inp=G[f'Demo pair {n} input']; out=G[f'Demo pair {n} output']
    s=segs_of(inp)
    tc=defaultdict(list); bc=defaultdict(list)
    for r in s[0]:
        for c,v in enumerate(inp[r]):
            if v: tc[v].append((r,c))
    for r in s[-1]:
        for c,v in enumerate(inp[r]):
            if v: bc[v].append((r,c))
    def norm(t,b):
        return pat(tc[t])==pat(bc[b])
    dup=[v for v in set(tc)&set(bc) if norm(v)][0]
    sel=max([v for v in set(tc)-set(bc)],key=lambda v:len(tc[v]))
    # output: what is relation of selector placement?
    ooc=[(r,c,out[r][c]) for r in range(len(out)) for c in range(15) if out[r][c]]
    tops=sorted({r for r,c,v in ooc if v==sel}); bots=sorted({r for r,c,v in ooc if v==dup})
    print('pair',n,'sel rows',tops,'dup rows',bots)

